module jtx1012_mmr(
    input             rst,
    input             clk,

    input             cs,
    input       [2:1] addr,
    input             rnw,
    input       [15:0] din, 
    output reg  [15:0] dout,
    input       [1:0] dsn,
    
    output [15:0] hpos,
    output [15:0] vpos,
    output       bank,

    // IOCTL dump
    input      [2:0] ioctl_addr,
    output reg [7:0] ioctl_din,
    // Debug
    input      [7:0] debug_bus,
    output reg [7:0] st_dout
);

localparam SIZE=8;
parameter SIMFILE="rest.bin",
          SEEK=0;
parameter [SIZE*8-1:0] INIT=0; // from high to low regs {mmr[3],mmr[2],mmr[1],mmr[0]}


reg  [ 7:0] mmr[0:SIZE-1];
integer     i;
`ifdef SIMULATION
reg [7:0] mmr_init[0:SIZE-1];
`endif

assign hpos = {
    mmr[1][7:0],
    mmr[0][7:0]
    };

assign vpos = {
    mmr[3][7:0],
    mmr[2][7:0]
    };

assign bank = {
    mmr[4][3]
    };


always @(posedge clk) begin
    if( rst ) begin
    `ifndef SIMULATION
        for(i=0;i<SIZE;i=i+1) mmr[i] <= INIT[i*8+:8];
    `else
        for(i=0;i<SIZE;i=i+1) mmr[i] <= mmr_init[i];
    `endif 
    dout <= 0;
    end else begin
        dout      <= {mmr[{addr,1'b1}],mmr[{addr,1'b0}]};
        st_dout   <= mmr[debug_bus[2:0]];
        ioctl_din <= mmr[ioctl_addr];
        if( cs & ~rnw ) begin
            if(!dsn[0]) mmr[{addr,1'b0}]<=din[ 7:0];
            if(!dsn[1]) mmr[{addr,1'b1}]<=din[15:8];
        end
        i = 0; // for Quartus linter
    end
end

`ifdef SIMULATION
/* verilator tracing_off */
integer f, fcnt, err;
initial begin
    f=$fopen(SIMFILE,"rb");
    err=$fseek(f,SEEK,0);
    if( f!=0 && err!=0 ) begin
        $display("Cannot seek file rest.bin to offset 0x%0X (%0d)",SEEK,SEEK);
    end
    if( f!=0 ) begin
        fcnt=$fread(mmr_init,f);
        $display("MMR %m - read %0d bytes from offset %0d",fcnt,SEEK);
        if( fcnt!=SIZE ) begin
            $display("WARNING: Missing %d bytes for %m.mmr",SIZE-fcnt);
        end else begin
            $display("\thpos = %X",{ mmr_init[1][7:0], mmr_init[0][7:0] });
            $display("\tvpos = %X",{ mmr_init[3][7:0], mmr_init[2][7:0] });
            $display("\tbank = %X",{ mmr_init[4][3] });
        end
    end else begin
        for(i=0;i<SIZE;i=i+1) mmr_init[i] = 0;
    end
    $fclose(f);
end
`endif

endmodule
